def build_completed_reminders_keyboard(page: int = 0, delete_mode: bool = False):
    rows = _reminder_completed_items()
    pages = max(1, (len(rows) + _REMINDER_COMPLETED_PAGE_SIZE - 1) // _REMINDER_COMPLETED_PAGE_SIZE)
